(()=>{'use strict';const photos=window.MEMORIES;if(!photos)return;const $=s=>document.querySelector(s);const image=i=>`images/${String(i+1).padStart(2,'0')}.jpg`;
const reveal=$('.reveal'),last=$('.last');$('#last-caption').textContent=photos[20].text;reveal.addEventListener('click',()=>{last.hidden=false;reveal.hidden=true;last.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});});
if(document.body.classList.contains('along')){const host=$('#story');photos.slice(0,20).forEach((m,i)=>{const row=document.createElement('article');row.className='story-row';const pic=document.createElement('div');pic.className='story-photo';const img=document.createElement('img');img.src=image(i);img.alt=m.alt;img.loading=i<2?'eager':'lazy';pic.append(img);const copy=document.createElement('div');copy.className='story-copy';const number=document.createElement('span');number.className='number';number.textContent=String(i+1).padStart(2,'0')+' / 20';const text=document.createElement('p');text.textContent=m.text;copy.append(number,text);row.append(pic,copy);host.append(row);});}
if(document.body.classList.contains('table')){const grid=$('#grid'),dialog=$('#viewer');let active=0,returnFocus=null;photos.slice(0,20).forEach((m,i)=>{const card=document.createElement('button');card.className='print';card.type='button';card.setAttribute('aria-label',`查看第 ${i+1} 张照片`);const img=document.createElement('img');img.src=image(i);img.alt='';img.loading='lazy';const n=document.createElement('span');n.textContent=String(i+1).padStart(2,'0');card.append(img,n);card.addEventListener('click',()=>{returnFocus=card;show(i);dialog.showModal();});grid.append(card);});function show(i){active=i;$('#viewer-img').src=image(i);$('#viewer-img').alt=photos[i].alt;$('#viewer-text').textContent=photos[i].text;$('#viewer-num').textContent=String(i+1).padStart(2,'0')+' / 20';$('#prev').disabled=i===0;$('#next').disabled=i===19;}$('#prev').addEventListener('click',()=>show(active-1));$('#next').addEventListener('click',()=>show(active+1));$('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.addEventListener('close',()=>returnFocus?.focus());}
})();
